    WHILE counter < 10 LOOP
        counter := counter + 1;
        total := total + counter;

        <<inner_loop>>
        WHILE total < 100 LOOP
            total := total + 5;
            EXIT inner_loop WHEN total > 50;
        END LOOP inner_loop;

        EXIT outer_loop WHEN total > 200;
    END LOOP outer_loop;

