        WHILE current_val % 20 != 0 LOOP
            current_val := current_val + 5;
            CONTINUE validation_loop WHEN current_val < 50;
        END LOOP validation_loop;

        result := result + current_val;
    END LOOP calculation_loop;

    RETURN result;
END;
$$ LANGUAGE plpgsql;

